package be.winnetrie.mod.simpleserverutilities.network; import be.winnetrie.mod.simpleserverutilities.SimpleServerUtilities;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.Identifier;
public record AchievementEditorResultPayload(boolean successful,String message,String achievementId,long requestId) implements CustomPacketPayload{public static final Type<AchievementEditorResultPayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(SimpleServerUtilities.MODID,"achievement_editor_result"));public static final StreamCodec<RegistryFriendlyByteBuf,AchievementEditorResultPayload> STREAM_CODEC=StreamCodec.of(AchievementEditorResultPayload::encode,AchievementEditorResultPayload::decode);public AchievementEditorResultPayload{message=PayloadBounds.string(message,512);achievementId=PayloadBounds.string(achievementId,64);requestId=Math.max(0L,requestId);}private static void encode(RegistryFriendlyByteBuf b,AchievementEditorResultPayload p){b.writeBoolean(p.successful);b.writeUtf(p.message,512);b.writeUtf(p.achievementId,64);b.writeVarLong(p.requestId);}private static AchievementEditorResultPayload decode(RegistryFriendlyByteBuf b){return new AchievementEditorResultPayload(b.readBoolean(),b.readUtf(512),b.readUtf(64),b.readVarLong());}@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}
